def main():
    out = []
    for slug, cat, title, aid, summary, rel, tags in ROWS:
        out.append({'id': 'scout-' + DATE + '-' + slug, 'date': DATE, 'category': cat,
                    'title': title, 'arxiv_id': aid, 'summary': summary, 'relevance': rel, 'tags': tags})
    db = lancedb.connect(DB)
    tb = db.open_table('nightly-scout')
    before = tb.count_rows()
    existing = set(r['id'] for r in tb.search().limit(20000).to_list())
    new = [r for r in out if r['id'] not in existing]
    print('rows before:', before, '| new:', len(new), '| dup skipped:', len(out) - len(new))
    if new:
        tb.add(new)
    print('rows after:', tb.count_rows())
    chk = tb.search().where("date = '2026-10-30'").limit(300).to_list()
    from collections import Counter
    print('verified for 2026-10-30:', len(chk), '| categories:', dict(Counter(r['category'] for r in chk)))


if __name__ == '__main__':
    main()
